public final class Stage20GTests implements FabricGameTest {
 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="stage20g",tickLimit=60)
 public void allTwelveHuntsPersistInvestigateSpawnDieAndRewardOnce(TestContext c){
 var w=c.getWorld();for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),Blocks.GRASS_BLOCK);for(int y=2;y<15;y++)c.setBlockState(new BlockPos(x,y,z),Blocks.AIR);}
 var at=c.getAbsolutePos(new BlockPos(30,2,24));var forest=w.getRegistryManager().get(net.minecraft.registry.RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.FOREST).orElseThrow();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var chunk=w.getChunkManager().getWorldChunk((at.getX()>>4)+x,(at.getZ()>>4)+z);if(chunk!=null)chunk.populateBiomes((a,b,d,s)->forest,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());}w.setBlockState(at.add(0,-1,2),Blocks.WATER.getDefaultState());
 var p=c.createMockCreativeServerPlayerInWorld();c.assertTrue(ContractSpecies.ENTITIES.size()==12,"Exactly twelve species");
 for(var species:ContractSpecies.ENTITIES.keySet()){
 p.refreshPositionAndAngles(at.getX()-18,at.getY(),at.getZ(),0,0);var hunt=Contracts.assign(p,ProceduralHunts.id(species));c.assertTrue(hunt.procedural.species().equals(species),"Species alias "+species);c.assertTrue(ContractInstance.fromNbt(hunt.toNbt()).procedural.equals(hunt.procedural),"Immutable rolled profile "+species);c.assertTrue(Investigations.prepare(p,hunt,at)&&hunt.investigation.clues.size()==2,"Two clues "+species);
 for(var clue:hunt.investigation.clues){p.refreshPositionAndAngles(clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()+.5,0,0);c.assertTrue(Investigations.inspect(p,clue.id),"Study "+species);}
 c.assertTrue(hunt.hunt.target==null&&hunt.investigation.stage==ContractInvestigation.Stage.LAIR_FOUND,"Separate lair "+species);p.refreshPositionAndAngles(at.getX()+.5,at.getY(),at.getZ()-2.2,0,0);c.assertTrue(Investigations.trySpawn(p,hunt),"Spawn safe existing entity "+species);var mob=(net.minecraft.entity.mob.MobEntity)w.getEntity(hunt.hunt.target);mob.setAiDisabled(true);if(mob instanceof com.witchersbestiary.entity.monster.WerewolfEntity wolf)c.assertTrue(!wolf.isHumanForm(),"Contract wolf remains a beast in daylight");c.assertTrue(hunt.id().equals(ProceduralHunts.binding(mob)),"Bound exact instance "+species);var saved=new NbtCompound();mob.saveNbt(saved);var copy=EntityType.loadEntityWithPassengers(saved,w,e->e);c.assertTrue(copy!=null&&hunt.id().equals(ProceduralHunts.binding(copy))&&ProceduralHunts.combat(copy).profile.equals(hunt.procedural),"Entity binding/profile NBT "+species);if(copy instanceof com.witchersbestiary.entity.monster.WerewolfEntity wolf)c.assertTrue(!wolf.isHumanForm()&&Math.abs(wolf.getMaxHealth()-hunt.procedural.health())<.01,"Wolf form/rolled health survives NBT");mob.damage(w.getDamageSources().genericKill(),100000);c.assertTrue(hunt.status()==ContractInstance.Status.COMPLETED,"Correct death "+species);Contracts.claim(p,hunt.id());boolean denied=false;try{Contracts.claim(p,hunt.id());}catch(IllegalStateException expected){denied=true;}c.assertTrue(denied,"Reward once "+species);mob.discard();}
 p.discard();c.complete();
 }
 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="stage20g-boards",tickLimit=40)
 public void visitedVillagePlacementAndLedgerSurviveReload(TestContext c){
 var w=c.getWorld();var root=c.getAbsolutePos(new BlockPos(24,2,24));var cp=new ChunkPos(root);
 for(int x=cp.getStartX();x<=cp.getEndX();x++)for(int z=cp.getStartZ();z<=cp.getEndZ();z++){w.setBlockState(new BlockPos(x,root.getY()-1,z),Blocks.GRASS_BLOCK.getDefaultState());int top=w.getTopY(net.minecraft.world.Heightmap.Type.WORLD_SURFACE,x,z);for(int y=root.getY();y<=Math.max(root.getY()+8,top);y++)w.setBlockState(new BlockPos(x,y,z),Blocks.AIR.getDefaultState());}
 var structure=w.getRegistryManager().get(net.minecraft.registry.RegistryKeys.STRUCTURE).get(net.minecraft.util.Identifier.of("minecraft:village_plains"));var bounds=new BlockBox(cp.getStartX(),root.getY(),cp.getStartZ(),cp.getEndX(),root.getY()+4,cp.getEndZ());
 var piece=new net.minecraft.structure.StructurePiece(net.minecraft.structure.StructurePieceType.BURIED_TREASURE,0,bounds){protected void writeNbt(net.minecraft.structure.StructureContext context,NbtCompound n){}public void generate(net.minecraft.world.StructureWorldAccess world,net.minecraft.world.gen.StructureAccessor accessor,net.minecraft.world.gen.chunk.ChunkGenerator generator,net.minecraft.util.math.random.Random random,BlockBox box,ChunkPos chunk,BlockPos pivot){}};
 var start=new net.minecraft.structure.StructureStart(structure,cp,0,new net.minecraft.structure.StructurePiecesList(java.util.List.of(piece)));String key=com.witchersbestiary.board.VisitedVillageBoards.offer(w,start);c.assertTrue(key!=null,"Registered supported village");for(int n=0;n<16;n++)com.witchersbestiary.board.VisitedVillageBoards.step(w.getServer());var ledger=com.witchersbestiary.board.VillageBoardLedger.get(w.getServer());c.assertTrue(ledger.outcome(key)!=null&&ledger.outcome(key).startsWith("PLACED"),"Terminal placement persisted");int count=0;for(int x=cp.getStartX();x<=cp.getEndX();x++)for(int z=cp.getStartZ();z<=cp.getEndZ();z++)if(w.getBlockState(new BlockPos(x,w.getTopY(net.minecraft.world.Heightmap.Type.WORLD_SURFACE,x,z)-1,z)).isOf(com.witchersbestiary.board.NoticeBoards.BLOCK))count++;c.assertTrue(count==3,"Physical one three-column board");var existing=com.witchersbestiary.board.VisitedVillageBoards.existingBoard(w,cp);c.assertTrue(existing!=null,"Palette detects board");w.setBlockState(existing.up(5),Blocks.OAK_LEAVES.getDefaultState());c.assertTrue(existing.equals(com.witchersbestiary.board.VisitedVillageBoards.existingBoard(w,cp)),"Covered board still prevents duplication");var saved=ledger.writeNbt(new NbtCompound(),w.getRegistryManager());var copy=com.witchersbestiary.board.VillageBoardLedger.read(saved,w.getRegistryManager());c.assertTrue(copy.outcome(key).equals(ledger.outcome(key)),"Ledger NBT reload retains terminal decision");com.witchersbestiary.board.VisitedVillageBoards.offer(w,start);for(int n=0;n<4;n++)com.witchersbestiary.board.VisitedVillageBoards.step(w.getServer());c.assertTrue(ledger.outcome(key).equals(copy.outcome(key)),"Idempotent revisit");c.complete();
 }
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage20g-ledger",tickLimit=20)
 public void futureLedgerIsPreservedReadOnly(TestContext c){var n=new NbtCompound();n.putInt("Schema",999);n.putString("Unknown","preserve");var ledger=com.witchersbestiary.board.VillageBoardLedger.read(n,c.getWorld().getRegistryManager());c.assertTrue(ledger.readOnly()&&ledger.writeNbt(new NbtCompound(),c.getWorld().getRegistryManager()).equals(n),"Future data preserved");boolean denied=false;try{ledger.record("key","value");}catch(IllegalStateException expected){denied=true;}c.assertTrue(denied,"No future ledger overwrite");c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="stage20g-live",tickLimit=40)
 public void genericTargetTicksAndReloadsWithoutLosingIdentity(TestContext c){var w=c.getWorld();for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),Blocks.GRASS_BLOCK);for(int y=2;y<14;y++)c.setBlockState(new BlockPos(x,y,z),Blocks.AIR);}var at=c.getAbsolutePos(new BlockPos(24,2,24));var forest=w.getRegistryManager().get(net.minecraft.registry.RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.FOREST).orElseThrow();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var chunk=w.getChunkManager().getWorldChunk((at.getX()>>4)+x,(at.getZ()>>4)+z);if(chunk!=null)chunk.populateBiomes((a,b,d,s)->forest,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());}var p=c.createMockCreativeServerPlayerInWorld();p.refreshPositionAndAngles(at.getX()-8,at.getY(),at.getZ(),0,0);var hunt=Contracts.assign(p,ProceduralHunts.id("endrega"));c.assertTrue(ProceduralHunts.spawn(p,hunt,at),"Generic live spawn");var mob=(net.minecraft.entity.mob.MobEntity)w.getEntity(hunt.hunt.target);mob.setAiDisabled(true);var id=mob.getUuid();var saved=new NbtCompound();
 c.runAtTick(6,()->{c.assertTrue(mob.isAlive()&&hunt.status()==ContractInstance.Status.ACCEPTED&&id.equals(hunt.hunt.target),"Generic controller accepts valid instance across ticks");mob.saveNbt(saved);mob.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);});
 c.runAtTick(9,()->{var copy=EntityType.loadEntityWithPassengers(saved,w,e->e);c.assertTrue(copy!=null&&w.spawnEntity(copy),"Same saved target reload");});
 c.runAtTick(15,()->{var copy=w.getEntity(id);c.assertTrue(copy!=null&&copy.isAlive()&&id.equals(hunt.hunt.target)&&hunt.status()==ContractInstance.Status.ACCEPTED,"No duplicate reservation or discard after reload");Contracts.cancel(p,hunt.id());copy.discard();p.discard();c.complete();});}
}
